// This file is generated by AI.

// 「暂存」菜单项的可见性 / 禁用状态 (git/util.ts 的 stageMenuItem)。
//
// 状态口径来自后端 `service/git.rs`: `staged` 取索引侧, `unstaged` 取工作区侧,
// 未跟踪文件落在 `unstaged` 里、字母是 `U` (来自 `WT_NEW`, 不是 porcelain 的 `??`)。

import { describe, expect, it } from 'vitest';

import type { GitStatus } from '../src/commands/git';
import { stageMenuItem } from '../src/git/util';

const project = 'C:\\Projects\\demo';
const abs = 'C:\\Projects\\demo\\game\\scene\\start.txt';
const rel = 'game/scene/start.txt';

function status(patch: Partial<GitStatus>): GitStatus {
  return { initialized: true, branch: 'main', staged: [], unstaged: [], identity: null, ...patch };
}

const file = (path: string, letter: GitStatus['staged'][number]['status']) => ({
  path,
  status: letter,
  additions: 0,
  deletions: 0,
});

describe('stageMenuItem', () => {
  it('没有状态 (还没读到) 时整项不出现', () => {
    expect(stageMenuItem(null, project, abs)).toEqual({ visible: false, disabled: true });
  });

  it('git 未初始化时整项不出现', () => {
    const result = stageMenuItem(status({ initialized: false }), project, abs);
    expect(result.visible).toBe(false);
  });

  it('未跟踪文件 (unstaged 里是 U) 不给「暂存」', () => {
    const result = stageMenuItem(status({ unstaged: [file(rel, 'U')] }), project, abs);
    expect(result).toEqual({ visible: false, disabled: true });
  });

  it('已暂存且工作区没有额外改动 -> 显示但禁用', () => {
    const result = stageMenuItem(status({ staged: [file(rel, 'A')] }), project, abs);
    expect(result).toEqual({ visible: true, disabled: true });
  });

  it('已跟踪但没有改动 (两份列表里都没有) -> 显示但禁用 (git add 是空操作)', () => {
    expect(stageMenuItem(status({}), project, abs)).toEqual({ visible: true, disabled: true });
  });

  it('工作区有改动 -> 显示且可用', () => {
    const result = stageMenuItem(status({ unstaged: [file(rel, 'M')] }), project, abs);
    expect(result).toEqual({ visible: true, disabled: false });
  });

  it('既已暂存又有新改动 -> 显示且可用', () => {
    const result = stageMenuItem(status({ staged: [file(rel, 'M')], unstaged: [file(rel, 'M')] }), project, abs);
    expect(result).toEqual({ visible: true, disabled: false });
  });

  it('只看当前文件: 别的路径的状态不影响它', () => {
    const other = 'game/scene/other.txt';
    const result = stageMenuItem(status({ unstaged: [file(other, 'M')] }), project, abs);
    expect(result).toEqual({ visible: true, disabled: true });
  });

  it('路径分隔符混用也能对上 (absToRel 归一成正斜杠)', () => {
    const withForwardSlash = 'C:/Projects/demo/game/scene/start.txt';
    const result = stageMenuItem(status({ unstaged: [file(rel, 'M')] }), project, withForwardSlash);
    expect(result).toEqual({ visible: true, disabled: false });
  });

  it('未跟踪同时被别的规则标成已暂存时不做误判 (U + staged 并存 -> 仍然显示)', () => {
    // 理论上不该出现, 但真出现时"隐藏"会让用户彻底无法暂存这个文件, 所以按可见处理
    const result = stageMenuItem(status({ staged: [file(rel, 'A')], unstaged: [file(rel, 'U')] }), project, abs);
    expect(result).toEqual({ visible: true, disabled: false });
  });
});
